def suma(lista):
    total = 0
    for x in lista:
        total += x
    return total

def hay_duplicados(lista):
    for i in range(len(lista)):
        for j in range(i + 1, len(lista)):
            if lista[i] == lista[j]:
                return True
    return False

def hay_duplicados_rapido(lista):
    vistos = set()
    for x in lista:
        if x in vistos:
            return True
        vistos.add(x)
    return False

def busqueda_binaria(arr, objetivo):
    izq, der = 0, len(arr) - 1
    while izq <= der:
        medio = (izq + der) // 2
        if arr[medio] == objetivo:
            return medio
        if arr[medio] < objetivo:
            izq = medio + 1
        else:
            der = medio - 1
    return -1

def contar_divisiones(n):
    pasos = 0
    while n > 1:
        n //= 2
        pasos += 1
    return pasos
